141	    private BigDecimal resolveBaseCharge(String procedureCode) {
142	        if (LEGACY_PRICING_TABLE.containsKey(procedureCode)) {
143	            return LEGACY_PRICING_TABLE.get(procedureCode);
144	        }
145	
146	        Optional<Procedure> procedure = procedureRepository.findByProcedureCode(procedureCode);
147	        if (procedure.isPresent()) {
148	            BigDecimal cost = procedure.get().getDefaultCost();
149	            if (cost != null && cost.compareTo(BigDecimal.ZERO) > 0) {
150	                return cost;
151	            }
152	        }
153	
154	        if (procedureCode.startsWith("XR")) {
155	            return new BigDecimal("125.00");
156	        } else if (procedureCode.startsWith("LAB")) {
157	            return new BigDecimal("45.00");
158	        } else if (procedureCode.startsWith("TEL")) {
159	            return new BigDecimal("75.00");
160	        } else if (procedureCode.startsWith("PROC")) {
161	            return new BigDecimal("150.00");
162	        } else if (procedureCode.startsWith("992")) {
163	            return new BigDecimal("110.00");
164	        }
165	
166	        return new BigDecimal("50.00");
167	    }
