366	    private BigDecimal applySurcharges(String procedureCode, BigDecimal amount, PricingContext context) {
367	        BigDecimal surcharged = amount;
368	
369	        if (context.getServiceDateTime() != null) {
370	            ZonedDateTime serviceTime = context.getServiceDateTime();
371	            int hour = serviceTime.getHour();
372	            DayOfWeek dayOfWeek = serviceTime.getDayOfWeek();
373	
374	            if (hour < 7 || hour > 18) {
375	                BigDecimal afterHours = SURCHARGE_RULES.get("AFTER_HOURS");
376	                if (afterHours != null) {
377	                    surcharged = surcharged.multiply(afterHours);
378	                }
379	            }
380	
381	            if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
382	                BigDecimal weekend = SURCHARGE_RULES.get("WEEKEND");
383	                if (weekend != null) {
384	                    surcharged = surcharged.multiply(weekend);
385	                }
386	            }
387	
388	            if (isHoliday(serviceTime.toLocalDate())) {
389	                BigDecimal holiday = SURCHARGE_RULES.get("HOLIDAY");
390	                if (holiday != null) {
391	                    surcharged = surcharged.multiply(holiday);
392	                }
393	            }
394	        }
395	
396	        if (Boolean.TRUE.equals(context.isUrgent())) {
397	            BigDecimal urgent = SURCHARGE_RULES.get("URGENT");
398	            if (urgent != null) {
399	                surcharged = surcharged.multiply(urgent);
400	            }
401	        }
402	
403	        if (Boolean.TRUE.equals(context.isStatOrder())) {
404	            String family = PROCEDURE_FAMILIES.get(procedureCode);
405	            if ("LABORATORY".equals(family)) {
406	                BigDecimal statLab = SURCHARGE_RULES.get("STAT_LAB");
407	                if (statLab != null) {
408	                    surcharged = surcharged.multiply(statLab);
409	                }
410	            }
411	        }
412	
413	        return surcharged;
414	    }
