416	    private BigDecimal applyTax(String procedureCode, BigDecimal amount, PricingContext context) {
417	        String family = PROCEDURE_FAMILIES.get(procedureCode);
418	        if (family == null) {
419	            family = deriveFamilyFromCode(procedureCode);
420	        }
421	
422	        BigDecimal taxRate = BigDecimal.ZERO;
423	
424	        switch (family) {
425	            case "OFFICE_VISIT_NEW":
426	            case "OFFICE_VISIT_ESTABLISHED":
427	            case "TELEHEALTH":
428	                taxRate = BigDecimal.ZERO;
429	                break;
430	            case "RADIOLOGY":
431	            case "LABORATORY":
432	                if (context.getState() != null) {
433	                    switch (context.getState()) {
434	                        case "CA":
435	                            taxRate = new BigDecimal("0.0725");
436	                            break;
437	                        case "TX":
438	                            taxRate = new BigDecimal("0.0625");
439	                            break;
440	                        case "NY":
441	                            taxRate = new BigDecimal("0.08");
442	                            break;
443	                        case "FL":
444	                            taxRate = new BigDecimal("0.06");
445	                            break;
446	                        default:
447	                            taxRate = new BigDecimal("0.05");
448	                    }
449	                } else {
450	                    taxRate = new BigDecimal("0.05");
451	                }
452	                break;
453	            case "PROCEDURE":
454	                taxRate = new BigDecimal("0.03");
455	                break;
456	            default:
457	                taxRate = new BigDecimal("0.05");
458	        }
459	
460	        if (Boolean.TRUE.equals(context.isTaxExempt())) {
461	            taxRate = BigDecimal.ZERO;
462	        }
463	
464	        BigDecimal taxAmount = amount.multiply(taxRate);
465	        return amount.add(taxAmount);
466	    }
