468	    private BigDecimal applyLegacyScript(String procedureCode, BigDecimal amount, PricingContext context) {
469	        try {
470	            Object script = applicationContext.getBean("legacyBillingAdjuster");
471	            if (script != null) {
472	                Object adjusted = InvokerHelper.invokeMethod(script, "adjust", new Object[]{amount, procedureCode, context});
473	                if (adjusted instanceof BigDecimal) {
474	                    return (BigDecimal) adjusted;
475	                } else if (adjusted instanceof Number) {
476	                    return new BigDecimal(adjusted.toString());
477	                }
478	                log.warn("Legacy script returned unexpected type: {}", adjusted.getClass());
479	            }
480	        } catch (Exception ex) {
481	            log.debug("Legacy script not available or failed: {}", ex.getMessage());
482	        }
483	
484	        return amount.add(new BigDecimal("12.34"));
485	    }
