491	    private String deriveFamilyFromCode(String procedureCode) {
492	        if (procedureCode.startsWith("992")) {
493	            if (procedureCode.startsWith("9920")) {
494	                return "OFFICE_VISIT_NEW";
495	            } else {
496	                return "OFFICE_VISIT_ESTABLISHED";
497	            }
498	        } else if (procedureCode.startsWith("XR")) {
499	            return "RADIOLOGY";
500	        } else if (procedureCode.startsWith("LAB")) {
501	            return "LABORATORY";
502	        } else if (procedureCode.startsWith("TEL")) {
503	            return "TELEHEALTH";
504	        } else if (procedureCode.startsWith("PROC")) {
505	            return "PROCEDURE";
506	        }
507	        return "UNKNOWN";
508	    }
