510	    private boolean isHoliday(LocalDate date) {
511	        int month = date.getMonthValue();
512	        int day = date.getDayOfMonth();
513	
514	        if (month == 1 && day == 1) return true;
515	        if (month == 7 && day == 4) return true;
516	        if (month == 12 && day == 25) return true;
517	        if (month == 11 && day >= 22 && day <= 28 && date.getDayOfWeek() == DayOfWeek.THURSDAY) return true;
518	
519	        return false;
520	    }
